// Initialize: start with empty conversations array and no cursor
return [{
  json: {
    locationId: '9oW28j2SxdPAmUhO5MDI',
    allConversations: [],
    nextPage: null,
    isFirstPage: true
  }
}];

// Accumulate conversations from this page and check for nextPage
const response = $input.first().json;
const conversations = response.conversations || [];

// Try to get previously accumulated conversations
let allConversations = [];
try {
  const prev = $('Accumulate & Check Next Page').first();
  allConversations = prev ? (prev.json.allConversations || []) : [];
} catch(e) {
  // First page, no previous accumulation
}

// Add this page's conversations
for (const conv of conversations) {
  allConversations.push({
    conversationId: conv.id,
    contactId: conv.contactId || '',
    contactName: conv.contactName || conv.fullName || '',
    lastMessageDate: conv.lastMessageDate || ''
  });
}

const nextPage = response.nextPage || null;

return [{
  json: {
    allConversations,
    nextPage,
    hasMore: !!nextPage,
    totalSoFar: allConversations.length,
    thisPageCount: conversations.length
  }
}];

// Output each conversation as a separate item for the loop
const allConversations = $input.first().json.allConversations;

if (!allConversations || allConversations.length === 0) {
  throw new Error('No conversations found for this location.');
}

return allConversations.map(conv => ({
  json: {
    conversationId: conv.conversationId,
    contactId: conv.contactId,
    contactName: conv.contactName,
    locationId: '9oW28j2SxdPAmUhO5MDI'
  }
}));

// Process all messages for this conversation:
// 1. Build full conversation TXT from ALL messages
// 2. Filter for TYPE_CALL with duration > 30s
// 3. Get contact info for naming
const response = $input.first().json;
const messages = response.messages || response.data || [];
const convData = $('Loop Conversations').first().json;
const conversationId = convData.conversationId;
const contactId = convData.contactId;
const contactName = convData.contactName;

// Sort messages chronologically
const sorted = [...messages].sort((a, b) => {
  const da = new Date(a.dateAdded || a.createdAt || 0);
  const db = new Date(b.dateAdded || b.createdAt || 0);
  return da - db;
});

// Build full conversation transcript from ALL message types
const conversationLines = sorted.map(msg => {
  const date = new Date(msg.dateAdded || msg.createdAt || '');
  const ts = date.toISOString().replace('T', ' ').substring(0, 16);
  const msgType = msg.type || msg.messageType || 'UNKNOWN';
  const direction = msg.direction || 'unknown';
  let body = msg.body || '';

  // For call messages, format with duration and status
  if (msgType === 'TYPE_CALL') {
    const duration = msg.meta?.call?.duration || msg.meta?.duration || 0;
    const status = msg.meta?.call?.status || msg.status || 'unknown';
    body = `Call - ${duration} seconds - ${status}`;
  }

  return `[${ts}] ${msgType} (${direction}): ${body}`;
});

const fullConversationText = conversationLines.join('\n');

// Filter for TYPE_CALL messages with duration > 30 seconds
const callMessages = sorted.filter(msg => {
  const msgType = msg.type || msg.messageType || '';
  if (msgType !== 'TYPE_CALL') return false;
  const duration = msg.meta?.call?.duration || msg.meta?.duration || 0;
  return duration > 30;
});

return [{
  json: {
    conversationId,
    contactId,
    contactName,
    fullConversationText,
    hasMessages: sorted.length > 0,
    totalMessages: sorted.length,
    callMessages: callMessages.map(msg => ({
      messageId: msg.id,
      direction: msg.direction || '',
      status: msg.meta?.call?.status || msg.status || '',
      duration: msg.meta?.call?.duration || msg.meta?.duration || 0,
      dateAdded: msg.dateAdded || msg.createdAt || ''
    })),
    hasCallMessages: callMessages.length > 0,
    callCount: callMessages.length,
    locationId: '9oW28j2SxdPAmUhO5MDI'
  }
}];

// Merge contact info with conversation data and build filenames
const contactResponse = $input.first().json;
const convData = $('Build Conversation & Filter Calls').first().json;

const contact = contactResponse.contact || contactResponse;
const firstName = (contact.firstName || contact.first_name || 'unknown').toLowerCase().trim();
const lastName = (contact.lastName || contact.last_name || 'unknown').toLowerCase().trim();

// Find earliest message date for the conversation file naming
const callMessages = convData.callMessages || [];
let earliestDate = new Date().toISOString().split('T')[0];
if (callMessages.length > 0) {
  earliestDate = new Date(callMessages[0].dateAdded || new Date()).toISOString().split('T')[0];
}

// Base filename: contactfirstname-contactlastname_YYYY-MM-DD
const baseFilename = `${firstName}-${lastName}_${earliestDate}`;

return [{
  json: {
    baseFilename,
    firstName,
    lastName,
    contactId: convData.contactId,
    conversationId: convData.conversationId,
    fullConversationText: convData.fullConversationText,
    hasMessages: convData.hasMessages,
    callMessages,
    hasCallMessages: convData.hasCallMessages,
    callCount: convData.callCount,
    locationId: convData.locationId,
    folderName: 'Strong Pilates Lakeview'
  }
}];

const searchResult = $input.first().json;
const files = searchResult.files || [];
const prevData = $('Build Filenames').first().json;

if (files.length > 0) {
  return [{
    json: {
      ...prevData,
      folderId: files[0].id,
      needsCreation: false
    }
  }];
} else {
  return [{
    json: {
      ...prevData,
      folderId: null,
      needsCreation: true
    }
  }];
}

const createResult = $input.first().json;
const prevData = $('Check Folder Exists').first().json;

return [{
  json: {
    ...prevData,
    folderId: createResult.id,
    needsCreation: false
  }
}];

// Normalize: ensure we have folderId and all data regardless of path
const data = $input.first().json;
return [{
  json: {
    folderId: data.folderId,
    baseFilename: data.baseFilename,
    firstName: data.firstName,
    lastName: data.lastName,
    contactId: data.contactId,
    conversationId: data.conversationId,
    fullConversationText: data.fullConversationText,
    hasMessages: data.hasMessages,
    callMessages: data.callMessages || [],
    hasCallMessages: data.hasCallMessages,
    callCount: data.callCount || 0,
    locationId: data.locationId,
    folderName: data.folderName
  }
}];

// Create the full conversation TXT as a binary file for upload
const data = $input.first().json;
const text = data.fullConversationText || '(No messages in conversation)';
const filename = `${data.baseFilename}_conversation.txt`;

const buffer = Buffer.from(text, 'utf-8');

return [{
  json: {
    ...data,
    conversationFilename: filename
  },
  binary: {
    conversationFile: {
      data: buffer.toString('base64'),
      mimeType: 'text/plain',
      fileName: filename
    }
  }
}];

// Output each call message as separate item for the inner loop
const data = $input.first().json;
const callMessages = data.callMessages || [];

return callMessages.map(call => ({
  json: {
    messageId: call.messageId,
    direction: call.direction,
    callStatus: call.status,
    callDuration: call.duration,
    dateAdded: call.dateAdded,
    baseFilename: data.baseFilename,
    contactId: data.contactId,
    conversationId: data.conversationId,
    folderId: data.folderId,
    locationId: data.locationId,
    firstName: data.firstName,
    lastName: data.lastName
  }
}));

// Extract the recording URL; handle 404 or missing gracefully
const response = $input.first().json;
const callData = $('Loop Call Messages').first().json;

const recordingUrl = response.url || response.recordingUrl || response.recording_url || response.data?.url || '';

// Check for error/404 responses
const isError = response.statusCode === 404 || response.error || response.status === 'error';

if (!recordingUrl || isError) {
  return [{
    json: {
      ...callData,
      recordingUrl: '',
      hasRecording: false,
      skipReason: isError ? 'Recording endpoint returned error/404' : 'No recording URL in response'
    }
  }];
}

return [{
  json: {
    ...callData,
    recordingUrl,
    hasRecording: true
  }
}];

// Build the per-call filename using call date
const data = $input.first().json;
const callDate = new Date(data.dateAdded || new Date());
const dateStr = callDate.toISOString().split('T')[0];
const callFilename = `${data.firstName}-${data.lastName}_${dateStr}`;

return [{
  json: {
    ...data,
    callFilename
  }
}];

// Format the ElevenLabs Scribe transcript into timestamped dialogue
const transcriptionData = $('Transcribe with ElevenLabs').first().json;
const callData = $('Build Call Filename').first().json;

const words = transcriptionData.words || [];

if (words.length === 0) {
  return [{ json: { transcript: '(No speech detected)', callFilename: callData.callFilename, folderId: callData.folderId } }];
}

// Group words into utterances by speaker changes
const utterances = [];
let currentSpeaker = null;
let currentWords = [];
let currentStart = 0;

for (const word of words) {
  const speaker = word.speaker_id !== undefined ? word.speaker_id : (word.speaker ?? null);

  if (speaker !== currentSpeaker && currentWords.length > 0) {
    utterances.push({
      speaker: currentSpeaker,
      text: currentWords.join(' '),
      start: currentStart
    });
    currentWords = [];
  }

  if (currentWords.length === 0) {
    currentStart = word.start_time || word.start || 0;
    currentSpeaker = speaker;
  }

  currentWords.push(word.text || word.word || '');
}

if (currentWords.length > 0) {
  utterances.push({
    speaker: currentSpeaker,
    text: currentWords.join(' '),
    start: currentStart
  });
}

function formatTime(seconds) {
  const h = Math.floor(seconds / 3600).toString().padStart(2, '0');
  const m = Math.floor((seconds % 3600) / 60).toString().padStart(2, '0');
  const s = Math.floor(seconds % 60).toString().padStart(2, '0');
  return `[${h}:${m}:${s}]`;
}

// Speaker 0 = Rep, Speaker 1 = Lead
const lines = utterances.map(u => {
  const speakerNum = parseInt(u.speaker, 10);
  let label;
  if (speakerNum === 0) {
    label = 'Rep';
  } else if (speakerNum === 1) {
    label = 'Lead';
  } else {
    label = `Speaker ${u.speaker}`;
  }
  return `${formatTime(u.start)} ${label}: ${u.text.trim()}`;
});

const transcript = lines.join('\n');

return [{
  json: {
    transcript,
    callFilename: callData.callFilename,
    folderId: callData.folderId
  }
}];

// Create transcript TXT binary for upload
const data = $input.first().json;
const transcript = data.transcript;
const filename = `${data.callFilename}_transcript.txt`;
const folderId = data.folderId;

const buffer = Buffer.from(transcript, 'utf-8');

return [{
  json: {
    filename,
    folderId
  },
  binary: {
    transcriptFile: {
      data: buffer.toString('base64'),
      mimeType: 'text/plain',
      fileName: filename
    }
  }
}];

// Log: no recording found for this call, skip gracefully
const callData = $input.first().json;
console.log(`SKIP: No recording for messageId=${callData.messageId} conversationId=${callData.conversationId} contactId=${callData.contactId} reason=${callData.skipReason}`);
return [{
  json: {
    status: 'skipped',
    reason: callData.skipReason || 'No recording URL',
    messageId: callData.messageId,
    conversationId: callData.conversationId,
    contactId: callData.contactId,
    timestamp: new Date().toISOString()
  }
}];

// Log transcription failure, continue to next call
const callData = $('Build Call Filename').first().json;
console.log(`ERROR: Transcription failed for messageId=${callData.messageId} contactId=${callData.contactId}`);
return [{
  json: {
    status: 'error',
    reason: 'Transcription failed or returned no words',
    messageId: callData.messageId,
    conversationId: callData.conversationId,
    contactId: callData.contactId,
    callFilename: callData.callFilename,
    timestamp: new Date().toISOString()
  }
}];

// Rate limit: wait 500ms between processing calls
await new Promise(resolve => setTimeout(resolve, 500));
return $input.all();

// No valid calls in this conversation, just log and continue
const data = $input.first().json;
console.log(`INFO: No calls with duration > 30s for conversationId=${data.conversationId} contactId=${data.contactId}`);
return [{
  json: {
    status: 'no_calls',
    conversationId: data.conversationId,
    contactId: data.contactId
  }
}];
